body{line-height:1.6}
::selection{background:var(--color-accent);color:var(--color-bg)}
a,button{transition:color .15s,background-color .15s}
:focus-visible{outline:2px solid var(--color-accent);outline-offset:4px}
[id]{scroll-margin-top:130px}
h1,h2,h3,h4{font-weight:600;line-height:1.12;letter-spacing:-.035em}
p{margin-top:0}
.site-header__inner{max-width:1280px;min-height:64px;padding:12px 24px;display:grid;grid-template-columns:1fr auto 1fr;gap:24px;border-inline:1px solid var(--rule)}
.site-identity{display:flex;align-items:center;gap:18px}
.entire-home{display:inline-flex;color:var(--color-text);flex-shrink:0}
.entire-logo{display:block;width:auto;height:24px}
.site-brand{font-family:var(--font-mono);font-size:11px;font-weight:400;letter-spacing:.04em;border-left:1px solid var(--rule);padding-left:18px}
.site-nav{margin:0;gap:12px;font-family:var(--font-body);font-size:14px;letter-spacing:0;text-transform:none}
.site-nav a{padding:6px 10px;border-radius:8px;white-space:nowrap}
.site-nav a:hover,.site-nav a[aria-current]{background:var(--color-neutral-100)}
.site-nav a::after{display:none}
.theme-toggle{justify-self:end;font-family:var(--font-body);font-size:13px;letter-spacing:0;text-transform:none;border-radius:8px;background:var(--color-surface);padding:6px 12px;color:var(--color-text);box-shadow:0 1px 2px rgb(0 0 0 / .04)}
.home-page main,.contribute-page main{max-width:1280px!important;padding-inline:clamp(20px,4vw,64px)!important;border-inline:1px solid var(--rule)}
.home-page main > section:first-child{position:relative;padding-top:clamp(48px,7vw,96px)!important}
.home-page main > section:first-child::before{content:"";position:absolute;inset:0;pointer-events:none;background-image:radial-gradient(var(--rule) 1px,transparent 1px);background-size:16px 16px;mask-image:linear-gradient(#000,transparent 65%)}
.home-page main > section:first-child > *{position:relative}
#mv-hero{font-size:clamp(64px,12vw,160px)!important;line-height:1!important;letter-spacing:-.055em!important}
.home-page main > section:first-child > div:first-child{font-size:11px!important;letter-spacing:.08em!important}
.home-page main > section:first-child > div:nth-of-type(2){grid-template-columns:1.2fr 1fr!important;align-items:start!important;gap:48px!important}
.home-page main > section:first-child dl{padding:20px 24px;background:var(--color-surface);border:1px solid var(--rule);border-radius:12px;font-size:12px!important}
.home-page main > section:first-child > div:nth-of-type(2) > p{font-size:clamp(20px,2.4vw,28px)!important;letter-spacing:-.02em;line-height:1.4!important}
.btn{border-radius:8px;font-family:var(--font-body);font-size:14px;font-weight:500;letter-spacing:0;text-transform:none;min-height:40px;padding:10px 16px;box-shadow:0 1px 2px rgb(0 0 0 / .04)}
.btn-primary{background:var(--color-accent);border-color:var(--color-accent);color:var(--color-bg)}
.btn-primary:hover{background:var(--color-accent-800);border-color:var(--color-accent-800);color:var(--color-bg)}
.btn-secondary{background:var(--color-surface);color:var(--color-text);border-color:var(--rule)}
.btn-ghost{box-shadow:none}
.blueprint{border-radius:12px;background:var(--color-surface)}
.blueprint .corner{display:none}
.duotone{border-radius:8px}
/* Preserve the original footage's colors instead of the old blueprint tint. */
.duotone::after,.duotone::before{display:none}
.duotone img,.duotone video{filter:none;mix-blend-mode:normal}
.card,.dialog,.input,.seg,.pathsw label{border-radius:8px}
.tag{border-radius:5px;font-size:11px;white-space:normal}
.table{font-size:13px}
.table th{font-family:var(--font-mono);font-weight:400;letter-spacing:.04em}
.table td{padding:10px 7px;overflow-wrap:anywhere}
.docs-layout{max-width:1280px!important;border-inline:1px solid var(--rule);grid-template-columns:210px minmax(0,1fr);gap:40px}
.docs-sidebar{top:64px;max-height:calc(100vh - 64px)}
.docs-sidebar__title{font-size:20px;line-height:1.2}
.docs-sidebar a{border-radius:6px}
.documentation-page .docs-content > section:first-child h1{font-size:clamp(42px,6vw,72px)!important;line-height:1.1!important}
.contribute-page main > nav[aria-label="On this page"]{top:64px!important}
.page-footer__inner{max-width:1280px;border-inline:1px solid var(--rule);font-size:10px;letter-spacing:.05em;padding:20px 32px}
