.entire-footer h2{margin:0;font-family:var(--font-body);font-size:14px;font-weight:400;line-height:20px;letter-spacing:0}
.entire-footer ul{list-style:none;padding:0;margin:24px 0 0;display:grid;gap:12px}
.entire-footer a{text-decoration:none;color:var(--muted)}
.entire-footer a:hover{color:var(--color-text)}
.entire-footer__logo{opacity:.2}
.entire-footer__logo .entire-logo{height:32px}
.entire-footer__bottom{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-top:40px}
.entire-footer__ask,.entire-footer__meta{display:flex;align-items:center;flex-wrap:wrap;gap:16px}
.entire-footer__meta{gap:24px;color:var(--muted)}
.entire-footer__agents{display:flex;gap:8px}
.entire-footer__agents a{display:flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:8px;background:var(--color-surface);border:1px solid var(--rule);box-shadow:0 1px 2px rgb(0 0 0 / .04)}
.entire-footer__agents svg{width:16px;height:16px}
@media(max-width:1000px){
  .entire-footer__columns{grid-template-columns:repeat(4,minmax(0,1fr))}
